// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 times) public {
        vm.assume(times <= 100);
        for (uint256 i = 0; i < times; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(player, 10);
            vm.prank(player);
            try c.play{value: 10}() {} catch {}
        }
        assertTrue(address(c).balance >= c.pot());
    }
}
